(window.webpackJsonp=window.webpackJsonp||[]).push([[68],{433:function(v,_,t){"use strict";t.r(_);var a=t(11),r=Object(a.a)({},(function(){var v=this,_=v._self._c;return _("ContentSlotsDistributor",{attrs:{"slot-key":v.$parent.slotKey}},[_("h2",{attrs:{id:"大冰主持人简介"}},[_("a",{staticClass:"header-anchor",attrs:{href:"#大冰主持人简介"}},[v._v("#")]),v._v(" 大冰主持人简介")]),v._v(" "),_("p",[_("code",[v._v("大冰")]),v._v("（原名冰田），中国著名主持人、作家、音乐人。1981年生于哈尔滨，内蒙古赤峰人。曾主持《开心麻花》，出版《摆渡人》，创作发行歌曲等。")]),v._v(" "),_("h2",{attrs:{id:"感悟"}},[_("a",{staticClass:"header-anchor",attrs:{href:"#感悟"}},[v._v("#")]),v._v(" 感悟")]),v._v(" "),_("p",[v._v("大冰老师很神奇，听他说话，让我踏实且发自内心的平和。一种从内而外的人生厚度，通过屏幕传递给观众。允许他人是他人，允许自己是自己。这是我很早就知道的一句话，且发自内心的认同并实践。但是从大冰老师嘴里再次听到，还是觉得深厚温暖，有着厚重的能量扑面而来。")]),v._v(" "),_("p",[v._v("这个世界很大有很多要探索，这是创造力的来源。在三五个方向前进，七八个方向好奇，核心是对生活、对自我、对他人、对社会的关系、态度和行动。引发我思考的是，有些时候浅谈兴趣或许是害怕实践。怕麻烦的本质是无法坦然面对自己。")]),v._v(" "),_("p",[v._v("还有大冰老师的疙瘩汤理论。儿童时期，人是清水，慢慢变成柠檬水，气泡水···和疙瘩汤。让我想到害人之心不可有，防人之心不可无这句话。随着人长大，经历多了，有些道理和人生经验让人懂得进退有度，半满即智慧。")]),v._v(" "),_("p",[v._v("最新看到大冰老师的切片，感悟是人要习得工具性技能，即生存根本，来维持生活。那么这个习得的时间最好是在学习能力强的黄金时期。当然学无止境，人可以一辈子在学习的路上，玩和学，看见和发现，人生就是一场生命体在时间维度上的体验。")]),v._v(" "),_("p",[v._v("另一个感悟是大冰老师说的人的社会属性和自然属性，大冰老师说社会属性为先，但我先达成了自然属性。某种程度上社会属性（保障自己存活）发展缓慢，这个属性需要锻炼且重要。")]),v._v(" "),_("p",[v._v("最近（04月01日）看大冰老师的切片，冰哥说未来ai等情感咨询，会以一种更科学陪伴时间更长的方式帮助大家认识到自己。但ai有很多局限，比如ai的分析只局限于认知当下的科学镜印，还存在一些当个体不能客观描述自身情况，情感操控自身，或自我主体性边界性不强，不能用元认知客观观察自身时，会出现出差较大的思维误区。所以现实个体的感悟和支持还是很有必要的。")]),v._v(" "),_("p",[v._v("最近（04月02日）看到大冰老师的切片，冰哥说世界上的人都不可信，这个世界就是一方烂透了的世界。这句话里掺杂了太多期望和失望。充满了阅历的一句话。我在想人活于世有所求就会有所失。接受来接受去，接受拥有接受失去，做简单的自己或许更容易和世界和解。如果人的烦恼是源自于人际交往和生存资源分配，那么边界，主体性，课题分离，自我完整，生存技能，都是需要锻炼的部分。一个人最大的责任是自己做决定，并为自己的决定负责。那么当做出了错误的选择，可以选择的方向是，买单离场，不钻牛角尖及时改变方向，向内回归自身。人的角色，先做自己，再做其他。")]),v._v(" "),_("p",[v._v("最近（04月04日）看到大冰老师的切片，一个25岁女生未婚先孕，男友不要孩子，不出钱，女生在反复犹豫要不要留下孩子以及要不要和男友结婚。冰哥说男人不能嫁，孩子留不留自己决定，钱是得要的，孩子留，钱得要，孩子不留，小产钱也得要，女生说对方留在她那四五万，男的说手术和后续保养身体不管她了，冰哥说四五万不够。我的思考是，女孩子的自我配得感较低，主体性差。在一开始接触男生时发现对方担不起事，遇到问题想逃避。但还是选择模糊这种客观信息，去美化关系。然后对方不负责任的弄出一条生命，还在反复思考要不要结婚，其实缺乏自己为自己兜底的能力，以及做决定做选择之后为自己的决定负责的能力。总结，人要尊重自己以及自己的感受。")]),v._v(" "),_("br"),v._v(" "),_("hr"),v._v(" "),_("div",{staticClass:"center-container"},[_("p",[v._v("📢 "),_("code",[v._v("版权声明")]),v._v("：本文为原创文章，著作权归 "),_("code",[v._v("【赵敏】")]),v._v(" 所有。"),_("code",[v._v("禁止转载，侵权必究")]),v._v("。")])]),_("br")])}),[],!1,null,null,null);_.default=r.exports}}]);